-- Mentorship form copied from BCIL's Google Form; CV clinic form removed (31 Oct 2026)
update public.forms set title='FCB 2027 Mentorship Registration', subtitle='Continued mentorship through BCIL Foundation', description=$q$Thank you for your interest in continued mentorship through BCIL Foundation. This form helps us understand your background, the areas in which you would like guidance, and what you hope to gain from mentorship. Please complete it only if you are genuinely interested in taking part.$q$, fields=$j$[{"key": "email", "label": "Email", "type": "email", "required": true}, {"key": "full_name", "label": "Full name", "type": "text", "required": true}, {"key": "phone", "label": "Phone / WhatsApp number", "type": "tel", "required": true}, {"key": "institution", "label": "University / Institution", "type": "text", "required": true}, {"key": "programme", "label": "Programme of study", "type": "text", "required": true}, {"key": "level", "label": "Current level", "type": "radio", "required": true, "options": ["Level 100", "Level 200", "Level 300", "Level 400", "Level 500", "Level 600", "Postgraduate", "Other"]}, {"key": "s2", "type": "section", "label": "Mentorship needs & goals", "help": "Tell us about the areas in which you would like guidance and what you hope to achieve through mentorship. Your responses will help BCIL Foundation understand your mentorship needs."}, {"key": "areas", "label": "In which areas would you like mentorship or guidance?", "type": "checkbox", "required": true, "help": "Select all that apply.", "options": ["Academic development and study strategies", "Career planning and professional development", "CV, cover letter and job/internship preparation", "Leadership and personal development", "Research and postgraduate education", "Scholarships and study-abroad opportunities", "Entrepreneurship and business development", "Networking and relationship building", "Managing university life and personal development", "Other"]}, {"key": "top_area", "label": "Of the areas you selected above, which ONE is your highest priority for mentorship right now?", "type": "select", "required": true, "options": ["Academic development and study strategies", "Career planning and professional development", "CV, cover letter and job/internship preparation", "Leadership and personal development", "Research and postgraduate education", "Scholarships and study-abroad opportunities", "Entrepreneurship and business development", "Networking and relationship building", "Managing university life and personal development"]}, {"key": "goal", "label": "What specific goal would you like mentorship to help you achieve within the next 6\u201312 months?", "type": "textarea", "required": true}, {"key": "challenge", "label": "What is the biggest challenge currently making it difficult for you to achieve this goal?", "type": "textarea", "required": true}, {"key": "hope_to_gain", "label": "What do you hope to gain from having a mentor?", "type": "checkbox", "required": true, "options": ["Advice and guidance", "Accountability and motivation", "Career or academic direction", "Practical skills and resources", "Networking and exposure", "Feedback on my goals and progress", "Learning from someone's experience", "Other"]}, {"key": "why", "label": "Briefly tell us why you are interested in joining the BCIL Foundation mentorship programme.", "type": "textarea", "required": true}, {"key": "s3", "type": "section", "label": "Commitment & availability", "help": "Effective mentorship requires commitment from both the mentor and mentee. Registration expresses your interest in mentorship but does not guarantee immediate assignment to a mentor. Matching depends on available mentors, areas of expertise, mentee needs and BCIL Foundation's mentorship capacity."}, {"key": "frequency", "label": "How often would you reasonably be available for a mentorship interaction?", "type": "radio", "required": true, "options": ["Once a week", "Every two weeks", "Once a month", "As needed, based on an agreed schedule"]}, {"key": "commitment", "label": "Are you willing to set mentorship goals, attend meetings, complete agreed action steps, and provide progress updates when required?", "type": "radio", "required": true, "options": ["Yes", "No"]}, {"key": "s4", "type": "section", "label": "Consent", "help": "The information you provide will be used by BCIL Foundation to administer its mentorship activities, understand your mentorship needs, communicate with you, and support mentor\u2013mentee matching where appropriate."}, {"key": "consent_use", "label": "I understand that the information I provide in this form may be used by BCIL Foundation for mentorship administration, communication, mentor\u2013mentee matching, and related programme monitoring.", "type": "radio", "required": true, "options": ["Yes, I understand and agree"]}, {"key": "consent_contact", "label": "I agree that BCIL Foundation may contact me using the email address, phone number, or WhatsApp number I provided regarding mentorship and related BCIL mentorship activities.", "type": "radio", "required": true, "options": ["Yes, I agree"]}, {"key": "confirm", "label": "Please confirm the following:", "type": "checkbox", "required": true, "options": ["The information I have provided is accurate to the best of my knowledge.", "I understand that submitting this form does not guarantee that I will immediately be assigned a mentor.", "If selected or matched, I will make a reasonable effort to participate actively in the mentorship process."]}]$j$::jsonb where slug='fcb27-mentorship';
delete from public.forms f where f.slug='cv-clinic' and not exists (select 1 from public.form_responses r where r.form_id=f.id);
update public.forms set is_open=false where slug='cv-clinic';
select slug, title, is_open, jsonb_array_length(fields) as questions from public.forms order by created_at;
